<?php
namespace Tests\Feature;
use App\Models\User;
use App\Services\SchoolFees;
use Database\Seeders\DatabaseSeeder;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Tests\TestCase;
class SchoolFeesTest extends TestCase
{
 use RefreshDatabase;
 protected function beforeRefreshingDatabase():void{if(!str_ends_with((string)config('database.connections.mysql.database'),'_test'))throw new \RuntimeException('Dedicated test DB required.');}
 protected function setUp():void{parent::setUp();\Carbon\Carbon::setTestNow('2026-10-17 09:00:00');\Carbon\CarbonImmutable::setTestNow('2026-10-17 09:00:00');}
 protected function tearDown():void{\Carbon\Carbon::setTestNow();\Carbon\CarbonImmutable::setTestNow();parent::tearDown();}
 private function fixture(string $code='A',string $role='owner'):array {
  if(!DB::table('roles')->exists())$this->seed(DatabaseSeeder::class);$sid=DB::table('schools')->insertGetId(['name'=>'Fees '.$code,'code'=>$code,'status'=>'active','timezone'=>'Asia/Karachi','currency'=>'PKR']);$cid=DB::table('campuses')->insertGetId(['school_id'=>$sid,'name'=>'Main','code'=>'MAIN','status'=>'active']);$user=User::factory()->create();$mid=DB::table('school_memberships')->insertGetId(['school_id'=>$sid,'user_id'=>$user->id,'status'=>'active']);$rid=DB::table('roles')->where('name',$role)->value('id');DB::table('membership_roles')->insert(['school_id'=>$sid,'membership_id'=>$mid,'role_id'=>$rid]);DB::table('membership_campuses')->insert(['school_id'=>$sid,'membership_id'=>$mid,'campus_id'=>$cid]);$session=DB::table('academic_sessions')->insertGetId(['school_id'=>$sid,'name'=>'2026-27','starts_on'=>'2026-04-01','ends_on'=>'2027-03-31','status'=>'active']);$class=DB::table('classes')->insertGetId(['school_id'=>$sid,'name'=>'Class 1','position'=>1]);$section=DB::table('sections')->insertGetId(['school_id'=>$sid,'campus_id'=>$cid,'academic_session_id'=>$session,'class_id'=>$class,'name'=>'A','capacity'=>20]);$student=DB::table('students')->insertGetId(['school_id'=>$sid,'admission_no'=>'S1','first_name'=>'Ali','admitted_on'=>'2026-04-01','status'=>'active']);$enrollment=DB::table('enrollments')->insertGetId(['school_id'=>$sid,'student_id'=>$student,'section_id'=>$section,'starts_on'=>'2026-04-01','status'=>'active']);$head=DB::table('fee_heads')->insertGetId(['school_id'=>$sid,'name'=>'Tuition','code'=>'TUIT']);return compact('sid','cid','user','mid','rid','session','class','section','student','enrollment','head');
 }
 private function login(array $f):void{$this->actingAs($f['user'])->withSession(['school_id'=>$f['sid']]);}
 private function planData(array $f,array $items=[]):array{return ['name'=>'Standard','academic_session_id'=>$f['session'],'class_id'=>$f['class'],'campus_id'=>$f['cid'],'starts_on'=>'2026-04-01','ends_on'=>'2027-03-31','items'=>$items?:[['fee_head_id'=>$f['head'],'amount'=>'1000.00','frequency'=>'monthly']]];}
 private function plan(array $f,array $items=[]):int{return $this->postJson('/app-api/fees/plans',$this->planData($f,$items))->assertOk()->json('id');}
 private function assign(array $f,int $plan):void{$this->postJson('/app-api/fees/assignments',['fee_plan_id'=>$plan,'enrollment_id'=>$f['enrollment'],'starts_on'=>'2026-04-01','reason'=>'School agreed rates'])->assertOk();}
 private function billing(string $month='2026-10'):array{return ['month'=>$month,'issued_on'=>'2026-10-17','due_on'=>'2026-10-20'];}
 private function issue(array $f):int{$p=$this->plan($f);$this->assign($f,$p);return $this->postJson('/app-api/fees/billing/generate',$this->billing())->assertOk()->json('invoice_ids.0');}
 private function collect(int $invoice,string $amount='400.00',?string $key=null,array $extra=[]):array{$d=array_replace(['amount'=>$amount,'method'=>'cash','paid_on'=>'2026-10-17','idempotency_key'=>$key??(string)Str::uuid()],$extra);$response=$this->postJson('/app-api/fees/invoices/'.$invoice.'/payments',$d)->assertOk();return [$response->json('id'),$d];}
 public function test_plans_assignments_discounts_and_invoice_snapshots_are_consistent():void {
  $f=$this->fixture();$this->login($f);$p=$this->plan($f);$this->assign($f,$p);$this->putJson('/app-api/fees/plans/'.$p,$this->planData($f))->assertUnprocessable();
  $con=['enrollment_id'=>$f['enrollment'],'fee_head_id'=>$f['head'],'kind'=>'percent','value'=>'12.55','starts_on'=>'2026-04-01','ends_on'=>'2027-03-31','reason'=>'Sibling discount agreed'];$cid=$this->postJson('/app-api/fees/concessions',$con)->assertOk()->json('id');
  $this->postJson('/app-api/fees/billing/preview',$this->billing())->assertJsonPath('rows.0.total','1000.00');$this->postJson('/app-api/fees/concessions/'.$cid.'/approve',[])->assertOk();$this->postJson('/app-api/fees/billing/preview',$this->billing())->assertJsonPath('rows.0.total','874.50');
  $id=$this->postJson('/app-api/fees/billing/generate',$this->billing())->assertOk()->json('invoice_ids.0');$this->assertDatabaseHas('invoice_items',['invoice_id'=>$id,'unit_amount'=>'1000.00','discount_amount'=>'125.50','line_total'=>'874.50']);
  $this->postJson('/app-api/fees/billing/generate',$this->billing())->assertOk()->assertJsonPath('issued',0)->assertJsonPath('skipped',1);$this->assertDatabaseCount('invoices',1);
  DB::table('fee_plan_items')->where('fee_plan_id',$p)->update(['amount'=>'2000.00']);$this->getJson('/app-api/fees/invoices/'.$id)->assertJsonPath('invoice.total','874.50')->assertJsonPath('items.0.unit_amount','1000.00');$this->artisan('database:verify')->assertSuccessful();
 }
 public function test_transfer_and_frequency_rules_prevent_duplicate_student_billing():void {
  $f=$this->fixture();$this->login($f);$annual=DB::table('fee_heads')->insertGetId(['school_id'=>$f['sid'],'name'=>'Annual','code'=>'ANNUAL']);$once=DB::table('fee_heads')->insertGetId(['school_id'=>$f['sid'],'name'=>'Admission','code'=>'ADM']);$p=$this->plan($f,[['fee_head_id'=>$f['head'],'amount'=>'1000','frequency'=>'monthly'],['fee_head_id'=>$annual,'amount'=>'500','frequency'=>'annual'],['fee_head_id'=>$once,'amount'=>'200','frequency'=>'once']]);$this->assign($f,$p);$this->postJson('/app-api/fees/billing/generate',$this->billing())->assertJsonPath('issued',1);$this->assertDatabaseHas('invoices',['total'=>'1700.00']);$this->postJson('/app-api/fees/billing/preview',$this->billing('2026-11'))->assertJsonPath('rows.0.total','1000.00');
  DB::table('enrollments')->where('id',$f['enrollment'])->update(['ends_on'=>'2026-10-10','status'=>'completed']);$new=DB::table('enrollments')->insertGetId(['school_id'=>$f['sid'],'student_id'=>$f['student'],'section_id'=>$f['section'],'starts_on'=>'2026-10-11','status'=>'active']);DB::table('student_fee_assignments')->insert(['school_id'=>$f['sid'],'enrollment_id'=>$new,'fee_plan_id'=>$p,'starts_on'=>'2026-10-11','ends_on'=>'2027-03-31']);$this->postJson('/app-api/fees/billing/generate',$this->billing())->assertJsonPath('issued',0);$this->assertDatabaseCount('invoices',1);
 }
 public function test_collection_is_idempotent_and_overpayments_and_reused_keys_are_rejected():void {
  $f=$this->fixture();$this->login($f);$i=$this->issue($f);[$pid,$d]=$this->collect($i);$this->postJson('/app-api/fees/invoices/'.$i.'/payments',$d)->assertOk()->assertJsonPath('id',$pid);$this->assertDatabaseCount('payments',1);$this->postJson('/app-api/fees/invoices/'.$i.'/payments',array_replace($d,['amount'=>'401']))->assertUnprocessable();$this->postJson('/app-api/fees/invoices/'.$i.'/payments',array_replace($d,['amount'=>'601','idempotency_key'=>(string)Str::uuid()]))->assertUnprocessable();$this->getJson('/app-api/fees/invoices/'.$i)->assertJsonPath('invoice.balance','600.00')->assertJsonPath('invoice.state','partial');$this->collect($i,'600');$this->getJson('/app-api/fees/invoices/'.$i)->assertJsonPath('invoice.state','paid');$this->postJson('/app-api/fees/invoices/'.$i.'/void',['reason'=>'Mistaken invoice'])->assertUnprocessable();
 }
 public function test_non_cash_account_scope_and_duplicate_transaction_reference_are_checked():void {
  $f=$this->fixture();$this->login($f);$i=$this->issue($f);$bank=DB::table('bank_accounts')->insertGetId(['school_id'=>$f['sid'],'campus_id'=>$f['cid'],'name'=>'Wallet','opening_balance'=>'0.00']);$d=['amount'=>'100','method'=>'jazzcash','paid_on'=>'2026-10-17','idempotency_key'=>(string)Str::uuid()];$this->postJson('/app-api/fees/invoices/'.$i.'/payments',$d)->assertUnprocessable();$d+=['bank_account_id'=>$bank,'reference'=>'TX-123'];$this->postJson('/app-api/fees/invoices/'.$i.'/payments',$d)->assertOk();$this->postJson('/app-api/fees/invoices/'.$i.'/payments',array_replace($d,['idempotency_key'=>(string)Str::uuid()]))->assertUnprocessable();$payment=DB::table('payments')->where('school_id',$f['sid'])->value('id');$refund=['kind'=>'refund','amount'=>'10','reason'=>'Bank refund correction','refund_method'=>'bank_transfer','refund_bank_account_id'=>$bank,'refund_reference'=>'RF-123','idempotency_key'=>(string)Str::uuid()];$this->postJson('/app-api/fees/payments/'.$payment.'/reversals',$refund)->assertOk();$this->postJson('/app-api/fees/payments/'.$payment.'/reversals',array_replace($refund,['idempotency_key'=>(string)Str::uuid()]))->assertUnprocessable();
 }
 public function test_partial_refund_needs_approval_restores_invoice_balance_and_preserves_receipt():void {
  $f=$this->fixture();$this->login($f);$i=$this->issue($f);[$payment]=$this->collect($i,'1000');$d=['kind'=>'refund','amount'=>'250','reason'=>'Approved parent refund','refund_method'=>'cash','idempotency_key'=>(string)Str::uuid()];$rev=$this->postJson('/app-api/fees/payments/'.$payment.'/reversals',$d)->assertOk()->json('id');$this->getJson('/app-api/fees/invoices/'.$i)->assertJsonPath('invoice.balance','0.00');$this->postJson('/app-api/fees/reversals/'.$rev.'/review',['decision'=>'approve'])->assertOk();$this->postJson('/app-api/fees/reversals/'.$rev.'/review',['decision'=>'approve'])->assertOk();$this->getJson('/app-api/fees/invoices/'.$i)->assertJsonPath('invoice.balance','250.00')->assertJsonPath('invoice.paid','750.00');$this->getJson('/app-api/fees/payments/'.$payment.'/receipt')->assertJsonPath('payment.amount','1000.00')->assertJsonPath('payment.net','750.00');$this->getJson('/app-api/fees/reports?from=2026-10-17&to=2026-10-17')->assertJsonPath('gross','1000.00')->assertJsonPath('refunds','250.00')->assertJsonPath('net','750.00')->assertJsonPath('outstanding','250.00');$this->postJson('/app-api/fees/payments/'.$payment.'/reversals',array_replace($d,['amount'=>'751','idempotency_key'=>(string)Str::uuid()]))->assertUnprocessable();
 }
 public function test_correction_approval_and_void_reissue_keep_original_history():void {
  $f=$this->fixture();$this->login($f);$i=$this->issue($f);[$p]=$this->collect($i,'1000');$rev=$this->postJson('/app-api/fees/payments/'.$p.'/reversals',['kind'=>'correction','amount'=>'1000','reason'=>'Payment recorded by mistake','idempotency_key'=>(string)Str::uuid()])->assertOk()->json('id');$this->postJson('/app-api/fees/reversals/'.$rev.'/review',['decision'=>'approve'])->assertOk();$this->postJson('/app-api/fees/invoices/'.$i.'/void',['reason'=>'Incorrect original fee invoice'])->assertOk();$this->postJson('/app-api/fees/billing/generate',$this->billing())->assertJsonPath('issued',1);$this->assertDatabaseCount('invoices',2);$this->assertDatabaseHas('invoices',['id'=>$i,'status'=>'void']);$this->assertDatabaseHas('audit_logs',['action'=>'fees.reversal_approved','target_id'=>$rev]);
 }
 public function test_opening_dues_is_only_created_before_other_invoices_and_bulk_errors_are_atomic():void {
  $f=$this->fixture();$this->login($f);$opening=['enrollment_id'=>$f['enrollment'],'amount'=>'2500','issued_on'=>'2026-10-17','due_on'=>'2026-10-20','reason'=>'Verified prior school balance'];$this->postJson('/app-api/fees/opening-dues',$opening)->assertOk();$this->postJson('/app-api/fees/opening-dues',$opening)->assertUnprocessable();$p=$this->plan($f);$this->assign($f,$p);$student=DB::table('students')->insertGetId(['school_id'=>$f['sid'],'admission_no'=>'S2','first_name'=>'Sara','admitted_on'=>'2026-04-01','status'=>'active']);DB::table('enrollments')->insert(['school_id'=>$f['sid'],'student_id'=>$student,'section_id'=>$f['section'],'starts_on'=>'2026-04-01','status'=>'active']);$this->postJson('/app-api/fees/billing/generate',$this->billing())->assertUnprocessable();$this->assertDatabaseCount('invoices',1);
 }
 public function test_permissions_and_tenant_campus_module_boundaries_are_enforced():void {
  $a=$this->fixture();$b=$this->fixture('B');$this->login($b);$invoice=$this->issue($b);$this->login($a);$this->getJson('/app-api/fees/invoices/'.$invoice)->assertNotFound();$this->getJson('/app-api/fees/invoices')->assertJsonPath('total',0);$this->postJson('/app-api/fees/assignments',['fee_plan_id'=>DB::table('fee_plans')->where('school_id',$b['sid'])->value('id'),'enrollment_id'=>$a['enrollment'],'starts_on'=>'2026-04-01','reason'=>'Invalid cross school'])->assertNotFound();
  $this->login($b);$rid=DB::table('roles')->where('name','accountant')->value('id');DB::table('membership_roles')->where('membership_id',$b['mid'])->update(['role_id'=>$rid]);$this->getJson('/app-api/fees/invoices/'.$invoice)->assertOk();$this->postJson('/app-api/fees/plans',$this->planData($b))->assertForbidden();$this->collect($invoice,'100');DB::table('school_role_permissions')->insert(['school_id'=>$b['sid'],'role_id'=>$rid,'permission_id'=>DB::table('permissions')->where('name','fees.collect')->value('id'),'enabled'=>false]);$this->postJson('/app-api/fees/invoices/'.$invoice.'/payments',['amount'=>'100','method'=>'cash','paid_on'=>'2026-10-17','idempotency_key'=>(string)Str::uuid()])->assertForbidden();DB::table('membership_campuses')->where('membership_id',$b['mid'])->delete();$this->getJson('/app-api/fees/invoices/'.$invoice)->assertNotFound();
 }
 public function test_integer_money_and_pending_concession_overlap_rounding_are_safe():void {
  $this->assertSame(101,SchoolFees::cents('1.01'));$this->assertSame('-0.25',SchoolFees::money(-25));$f=$this->fixture();$this->login($f);$p=$this->plan($f,[['fee_head_id'=>$f['head'],'amount'=>'0.05','frequency'=>'monthly']]);$this->assign($f,$p);$d=['enrollment_id'=>$f['enrollment'],'fee_head_id'=>$f['head'],'kind'=>'percent','value'=>'50','starts_on'=>'2026-04-01','ends_on'=>'2027-03-31','reason'=>'Rounding verification'];$c=$this->postJson('/app-api/fees/concessions',$d)->assertOk()->json('id');$this->postJson('/app-api/fees/concessions/'.$c.'/approve',[])->assertOk();$c2=$this->postJson('/app-api/fees/concessions',$d)->assertOk()->json('id');$this->postJson('/app-api/fees/concessions/'.$c2.'/approve',[])->assertUnprocessable();$this->postJson('/app-api/fees/billing/preview',$this->billing())->assertJsonPath('rows.0.total','0.02');
 }
 public function test_accountant_cannot_approve_refund_and_unauthorized_provider_has_no_access():void {
  $f=$this->fixture();$this->login($f);$i=$this->issue($f);[$payment]=$this->collect($i,'1000');DB::table('membership_roles')->where('membership_id',$f['mid'])->update(['role_id'=>DB::table('roles')->where('name','accountant')->value('id')]);$rev=$this->postJson('/app-api/fees/payments/'.$payment.'/reversals',['kind'=>'correction','amount'=>'50','reason'=>'Wrong recording correction','idempotency_key'=>(string)Str::uuid()])->assertOk()->json('id');$this->postJson('/app-api/fees/reversals/'.$rev.'/review',['decision'=>'approve'])->assertForbidden();
  $provider=User::factory()->create();DB::table('platform_admins')->insert(['user_id'=>$provider->id,'active'=>true]);$this->actingAs($provider)->withSession(['school_id'=>$f['sid']])->getJson('/app-api/fees/setup')->assertForbidden();
 }
 public function test_fee_module_license_and_pakistan_date_boundaries_are_checked():void {
  $f=$this->fixture();$this->login($f);$i=$this->issue($f);[$payment]=$this->collect($i,'1000');DB::table('payments')->where('id',$payment)->update(['paid_at'=>'2026-10-16 20:00:00']);$this->getJson('/app-api/fees/reports?from=2026-10-17&to=2026-10-17')->assertJsonPath('gross','1000.00');$this->getJson('/app-api/fees/reports?from=2026-10-16&to=2026-10-16')->assertJsonPath('gross','0.00');
  \Carbon\Carbon::setTestNow('2026-10-18 09:00:00');\Carbon\CarbonImmutable::setTestNow('2026-10-18 09:00:00');$rev=$this->postJson('/app-api/fees/payments/'.$payment.'/reversals',['kind'=>'refund','refund_method'=>'cash','amount'=>'100','reason'=>'Refund from previous day','idempotency_key'=>(string)Str::uuid()])->assertOk()->json('id');$this->postJson('/app-api/fees/reversals/'.$rev.'/review',['decision'=>'approve'])->assertOk();$this->getJson('/app-api/fees/reports?from=2026-10-18&to=2026-10-18')->assertJsonPath('net','-100.00')->assertJsonPath('outstanding','100.00');
  $license=\App\Services\LicenseService::ensure($f['sid']);DB::table('subscriptions')->insert(['school_id'=>$f['sid'],'plan_id'=>DB::table('plans')->value('id'),'license_id'=>$license->id,'kind'=>'paid','student_limit'=>1000,'campus_limit'=>2,'modules'=>json_encode(['student_admissions']),'package_name'=>'No fees','starts_on'=>'2026-01-01','ends_on'=>'2027-12-31','price'=>'100','status'=>'active']);$this->getJson('/app-api/fees/setup')->assertForbidden();
 }

}
